import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BN3Eol-0.js";const p=JSON.parse('{"title":"Adding a new program — runbook","description":"","frontmatter":{},"headers":[],"relativePath":"guides/program-addition-runbook.md","filePath":"guides/program-addition-runbook.md"}'),s={name:"guides/program-addition-runbook.md"};function n(d,e,i,c,l,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="adding-a-new-program-—-runbook" tabindex="-1">Adding a new program — runbook <a class="header-anchor" href="#adding-a-new-program-—-runbook" aria-label="Permalink to &quot;Adding a new program — runbook&quot;">​</a></h1><p>The single prescribed path for bringing a new <strong>program</strong> (the editorial layer over missions + fleet, PRD-029) into Orrery — program by program. Companion to two docs you must read first:</p><ul><li><strong><a href="./../prd/PRD-029">PRD-029</a></strong> — the <em>structure</em>: the editorial spine, the roster model, embedded images, badges, deep-links.</li><li><strong><a href="./programs-editorial-voice">programs-editorial-voice.md</a></strong> — the <em>voice</em>: the modern-Wired-field-historian register every section (and every mission dispatch) is written in.</li></ul><p>Analogous to the <a href="./mission-addition-runbook">mission-addition runbook</a> and the <a href="./flyby-body-addition-runbook">flyby-body runbook</a>. <strong>Read this before hand-authoring program JSON.</strong></p><p>Worked example throughout: <strong>Apollo</strong> (<code>apollo</code>) — the reference implementation. When in doubt, open Apollo&#39;s files and match them.</p><h2 id="the-model-—-hand-authored-json-over-the-existing-catalog-gated-by-validate-data" tabindex="-1">The model — hand-authored JSON over the <em>existing</em> catalog, gated by <code>validate-data</code> <a class="header-anchor" href="#the-model-—-hand-authored-json-over-the-existing-catalog-gated-by-validate-data" aria-label="Permalink to &quot;The model — hand-authored JSON over the *existing* catalog, gated by `validate-data`&quot;">​</a></h2><p>A program is static JSON, validated by fail-closed gates. Three rules define the model:</p><ol><li><strong>A program groups + narrates what already exists — it does not expand the curated set.</strong> The roster <strong>links</strong> curated flagship missions/fleet we already model, and <strong>names</strong> the historically-important missions we <em>don&#39;t</em> (context, no page). Adding a program never obligates a new mission or fleet entry. (If a program genuinely needs a new mission, that&#39;s the <a href="./mission-addition-runbook">mission runbook</a> first, as its own decision.)</li><li><strong>The substance is editorial, in one voice.</strong> Every program is a full-page editorial piece (like <code>/science</code>), not a data card. Write it against <code>programs-editorial-voice.md</code> — Apollo is the calibrated reference.</li><li><strong>English-first.</strong> Ship the en-US editorial; translation follows when the locale tier ships (§11). <code>npm run validate-data</code> is your checklist — author → validate → fix what it flags → repeat until the only reds are the known English-first locale gaps.</li></ol><hr><h2 id="touchpoints-in-order" tabindex="-1">Touchpoints (in order) <a class="header-anchor" href="#touchpoints-in-order" aria-label="Permalink to &quot;Touchpoints (in order)&quot;">​</a></h2><h3 id="_1-·-base-record-—-static-data-programs-id-json" tabindex="-1">1 · Base record — <code>static/data/programs/{id}.json</code> <a class="header-anchor" href="#_1-·-base-record-—-static-data-programs-id-json" aria-label="Permalink to &quot;1 · Base record — `static/data/programs/{id}.json`&quot;">​</a></h3><p>Structured, non-translatable data. Schema: <code>static/data/schemas/program.schema.json</code>. Fields: <code>id</code>, <code>kind</code> (<code>crewed-campaign</code> | <code>robotic-campaign</code> | <code>station</code> | <code>infrastructure</code> | <code>funding-line</code>), <code>agency</code> / <code>agencies</code>, <code>country</code>, <code>start_year</code> / <code>end_year</code>, <code>status</code>, <code>epoch</code> (drives era grouping), <code>hero</code>, <code>roster</code>, <code>related_programs</code>, <code>badge</code>, <code>see_also</code>, <code>links</code>.</p><h3 id="_2-·-roster-—-link-flagships-name-context" tabindex="-1">2 · Roster — link flagships, name context <a class="header-anchor" href="#_2-·-roster-—-link-flagships-name-context" aria-label="Permalink to &quot;2 · Roster — link flagships, name context&quot;">​</a></h3><p><code>roster[]</code> items have these shapes (<a href="./../uxs/decisions/UXD-033-program-roster-links-and-milestones">UXD-033</a>):</p><ul><li><strong>Linked</strong> (we model it): <code>{ ref: &quot;mission&quot; | &quot;fleet&quot; | &quot;module&quot;, linked_id, role, note }</code> — a mission row is clickable and drives the timeline + master-detail pane; a fleet row is a hardware card; a module row opens the station page (<code>/&lt;program id&gt;?module=&lt;id&gt;</code>).</li><li><strong>Context</strong> (we don&#39;t): <code>{ name, year, note }</code> — flat text, no link. This is how a program legitimately mentions missions outside the curated set (Soviet lunar names Zond 5, whose mission is not modelled).</li><li><strong>Context with a link</strong> (an event about an entry we model): <code>{ name, year, note, link: { ref: &quot;fleet&quot; | &quot;module&quot;, id, station? } }</code> — Challenger&#39;s loss links the Challenger craft; Columbus under ESA human spaceflight links <code>/iss?module=columbus</code> (<code>station: &quot;iss&quot;</code>). A <code>module</code> link names its station.</li><li><strong>Milestone</strong>: a context row plus <code>milestone: true</code> — an episode, phase, decision or plan inside the program (not a flight, a craft or a test). Drawn under &quot;Milestones&quot; after Missions, no link, no card.</li></ul><p><strong>A row that names an entry that exists must link to it</strong> (as <code>linked_id</code> for a mission, or <code>link</code> for a craft or module); <code>src/lib/programs-roster.test.ts</code> fails on a name-only row equal to a mission, craft or module name. Hardware rows are the flown vehicles of the program&#39;s linked missions (<code>fleet_refs</code>): launchers, spacecraft, landers, orbiters and rovers; launch sites are left out.</p><p><strong>Roster text is English in the base record and translated per locale.</strong> A row&#39;s <code>note</code>, and the <code>name</code> of a name-only row, are English here; a locale shows them through its overlay&#39;s <code>roster</code> map (§3), or English where it has none. A <strong>deployed-from</strong> note (a probe launched from the Shuttle is not a Shuttle mission) goes on the linked row, e.g. <code>{ &quot;linked_id&quot;: &quot;galileo&quot;, &quot;ref&quot;: &quot;mission&quot;, &quot;year&quot;: 1989, &quot;note&quot;: &quot;deployed from Atlantis&#39;s payload bay on STS-34 …&quot; }</code>.</p><p>Keep cross-refs symmetric where the linked entity points back (e.g. a mission&#39;s <code>program</code>, if/when added).</p><h3 id="_3-·-editorial-overlay-—-i18n-src-en-us-programs-id-json" tabindex="-1">3 · Editorial overlay — <code>i18n-src/en-US/programs/{id}.json</code> <a class="header-anchor" href="#_3-·-editorial-overlay-—-i18n-src-en-us-programs-id-json" aria-label="Permalink to &quot;3 · Editorial overlay — `i18n-src/en-US/programs/{id}.json`&quot;">​</a></h3><p>The spine, en-US prose first. Schema: <code>program-overlay.schema.json</code>. Required: <code>name</code>, <code>tagline</code>, <code>the_land</code>, <code>goals</code>, <code>outcome</code>, <code>narrative</code>, <code>legacy</code>, <code>lessons</code>. Each spine section is an <strong>ordered block list</strong>: <code>{ type: &quot;prose&quot;, md }</code> and <code>{ type: &quot;figure&quot;, image, caption, align }</code>. Write every block against <code>programs-editorial-voice.md</code> §5 (per-section register). Do <strong>not</strong> repeat the hero lower down; prefer more, smaller, single-subject figures; no collages.</p><p><strong>Roster text in a locale overlay</strong> — <code>i18n-src/{locale}/programs/{id}.json</code> may carry <code>roster: { &quot;&lt;key&gt;&quot;: { &quot;note&quot;: &quot;…&quot;, &quot;name&quot;: &quot;…&quot; } }</code>, only for the rows that locale translates; <code>getProgram()</code> lays it over the base roster (<code>src/lib/program-roster-overlay.js</code>). The key is the row&#39;s <code>rosterKey()</code>, never its array position, so inserting a row keeps every translation: <strong><code>ref:linked_id</code></strong> for a linked row (<code>mission:galileo</code>, <code>fleet:cassini</code> — a mission and its craft share an id), else the row&#39;s <strong>English <code>name</code></strong> (<code>STS-1</code>). <code>note</code> replaces the note of any row; <code>name</code> replaces the name of a name-only row only (a linked row&#39;s name comes from the linked entry). There is no <code>roster</code> in the en-US overlay: the English is the base record, so one source. The base rows that are not in a locale&#39;s map show English, and are counted by <code>node scripts/i18n-coverage-scan.mjs</code> as <code>rosterMissing</code> per locale (reported, not gated); a key with no row is an <code>extraKey</code>, and <code>src/lib/program-roster-overlay.test.ts</code> fails on one. Staleness: <code>stale-overlays.mjs --manifest=check</code> (in <code>validate-data</code>) hashes every base roster note and name-only name under <code>programs-roster/{id}.json</code>, so a new or edited English note fails until the translations are re-checked and <code>--manifest=write</code> is run.</p><h3 id="_4-·-images-—-reuse-first" tabindex="-1">4 · Images — reuse-first <a class="header-anchor" href="#_4-·-images-—-reuse-first" aria-label="Permalink to &quot;4 · Images — reuse-first&quot;">​</a></h3><p><code>figure.image</code> is either <strong>reuse</strong> (<code>{ reuse: &quot;missions/apollo11/03&quot; }</code> or <code>{ reuse: &quot;fleet/saturn-v/02&quot; }</code> — resolves into an existing gallery, provenance inherited) or <strong>new</strong> (<code>{ id: &quot;the-land/sputnik&quot; }</code> under <code>static/images/programs/{id}/</code>, which needs its own provenance + <code>/credits</code> entry). Reuse covers most beats; only resource what the editorial genuinely lacks.</p><h3 id="_5-·-badge-—-program-insignia-pd-cc-only" tabindex="-1">5 · Badge — program insignia, PD/CC only <a class="header-anchor" href="#_5-·-badge-—-program-insignia-pd-cc-only" aria-label="Permalink to &quot;5 · Badge — program insignia, PD/CC only&quot;">​</a></h3><p>Add the program&#39;s insignia via the badge pipeline: an entry in <code>static/data/badge-sources.json</code> (<code>kind: &quot;program&quot;</code>), then <code>tsx scripts/fetch-badges.ts</code> → saves the original to <code>masters/badges/programs/{id}.&lt;ext&gt;</code> (git-LFS) and writes the derived <code>static/images/badges/programs/{id}.webp</code> (one 256 px icon) + <code>badges.json</code> + <code>badge-provenance.json</code>. It&#39;s a distinct lane from the display ladder — see <a href="./../../scripts/IMAGE-PIPELINE">IMAGE-PIPELINE.md §&quot;Badges are a separate lane&quot;</a>. You do <strong>not</strong> need <code>git lfs pull</code> to source a badge; the dedup gate skips LFS stubs per file. <strong>Licensing bar: Public Domain / CC only.</strong> Mission patches and program insignia are usually available; <strong>per-vehicle badges for older hardware are usually trademarked contractor logos and are excluded</strong> (Apollo fleet correctly carries none). The UI gates every badge on <code>badges.json</code>, so an absent badge simply renders nothing — never a 404.</p><h3 id="_6-·-dispatches-—-mandatory-follow-up-missions-hardware" tabindex="-1">6 · Dispatches — <strong>MANDATORY follow-up</strong> (missions + hardware) <a class="header-anchor" href="#_6-·-dispatches-—-mandatory-follow-up-missions-hardware" aria-label="Permalink to &quot;6 · Dispatches — **MANDATORY follow-up** (missions + hardware)&quot;">​</a></h3><p>For <strong>every mission <em>and</em> fleet asset the roster links</strong> (<code>ref: &quot;mission&quot; | &quot;fleet&quot;</code> + <code>linked_id</code>), author a <strong><code>dispatch</code></strong> per <code>programs-editorial-voice.md</code> §6 — one lead paragraph rendered at the top of the entry&#39;s OVERVIEW tab. The angle depends on the target:</p><ul><li><strong>Missions</strong> → the <em>why-it-matters</em> → <code>i18n-src/en-US/missions/{dest}/{id}.json</code>.</li><li><strong>Fleet/hardware</strong> → the <em>innovation + purpose</em> of that unique asset (what made it a first, why it had to exist) → <code>i18n-src/en-US/fleet/{category}/{id}.json</code>.</li></ul><p>Neither is a spec/fact rehash. <strong>Launch-site assets propagate automatically</strong> — a <code>dispatch</code> on a <code>fleet/launch-site/*</code> entry is carried through by <code>earth-launch-site-adapter.ts</code> and shows on the <code>/earth</code> pad panel too (above the coordinate grid), with zero extra work. One dispatch, three surfaces: <code>/fleet</code>, the program roster, and <code>/earth</code>. Do this <strong>while the program&#39;s context is loaded</strong>, not later. Context-only roster entries (no <code>linked_id</code>) get none. This step is not optional — a program is not done until every linked mission and asset carries its dispatch.</p><h3 id="_7-·-deep-links-—-see-also" tabindex="-1">7 · Deep-links — <code>see_also</code> <a class="header-anchor" href="#_7-·-deep-links-—-see-also" aria-label="Permalink to &quot;7 · Deep-links — `see_also`&quot;">​</a></h3><p>The program page draws only the sections that have rows (no hardware row: no Hardware heading), shows <code>related_programs</code> as a card rail (so list ids that exist in <code>programs/index.json</code>; do not repeat them as <code>see_also</code> rows of kind <code>program</code>, the page drops those) and <code>surface_sites</code> as a card rail (Earth objects such as <code>iss</code> link <code>/earth?object=&lt;id&gt;</code>). <code>see_also[]</code> (<code>{ label, href, kind: &quot;body&quot; | &quot;science&quot; | &quot;explore&quot; | &quot;fleet&quot; | &quot;gallery&quot; }</code>) sends the reader into the rest of Orrery — <code>/moon</code>, <code>/science</code> articles, <code>/explore</code>. Every program should hand off to the surfaces that continue its story.</p><h3 id="_8-·-prerender-—-src-routes-programs-id-page-ts" tabindex="-1">8 · Prerender — <code>src/routes/programs/[id]/+page.ts</code> <a class="header-anchor" href="#_8-·-prerender-—-src-routes-programs-id-page-ts" aria-label="Permalink to &quot;8 · Prerender — `src/routes/programs/[id]/+page.ts`&quot;">​</a></h3><p>No list to edit: <code>scripts/site-routes.mjs</code> (<code>programsRoutes</code>) makes every program in <code>static/data/programs/index.json</code> (step 9) a prerender entry, in every locale. The universal <code>load</code> builds the roster&#39;s <code>missionDetails</code> map — it must thread <code>event.fetch</code> (not global <code>fetch</code>) through <code>getProgram</code> / <code>getMissionIndex</code> / <code>getMission</code>, or relative data URLs throw at build.</p><h3 id="_9-·-index-—-static-data-programs-index-json" tabindex="-1">9 · Index — <code>static/data/programs/index.json</code> <a class="header-anchor" href="#_9-·-index-—-static-data-programs-index-json" aria-label="Permalink to &quot;9 · Index — `static/data/programs/index.json`&quot;">​</a></h3><p>Add the program&#39;s index entry (id, name, tagline, agency, years, epoch, hero) so it appears on <code>/programs</code>, grouped by era <strong>and</strong> by agency.</p><h3 id="_10-·-nav-—-already-wired" tabindex="-1">10 · Nav — already wired <a class="header-anchor" href="#_10-·-nav-—-already-wired" aria-label="Permalink to &quot;10 · Nav — already wired&quot;">​</a></h3><p><code>/programs</code> is already in <code>Nav.svelte</code> (after Fleet). No per-program nav step.</p><h3 id="_11-·-i18n-—-english-first-then-translate-at-tier" tabindex="-1">11 · i18n — English-first, then translate at tier <a class="header-anchor" href="#_11-·-i18n-—-english-first-then-translate-at-tier" aria-label="Permalink to &quot;11 · i18n — English-first, then translate at tier&quot;">​</a></h3><p>Rebuild the bundle after any overlay edit: <code>node scripts/build-i18n-bundles.mjs</code> (writes <code>static/data/i18n/{locale}.json</code>; the bundle key is <code>programs/{id}.json</code> — <strong>with</strong> the <code>.json</code>). Programs ship <strong>en-US only</strong> at first. <code>validate-data</code> enforces all-14-locale overlays as core content, so a new program shows 13 expected locale-gap reds until translated — wire the <strong>programs known-gap exemption</strong> for the English-first phase (mirrors how audio/missions phase locales), and translate when the program&#39;s locale tier ships. The roster&#39;s notes and name-only names are translated separately, through the overlay&#39;s <code>roster</code> map (§3); an untranslated row is a <code>rosterMissing</code> count in the coverage scan, not a <code>validate-data</code> red.</p><h3 id="_12-·-validate" tabindex="-1">12 · Validate <a class="header-anchor" href="#_12-·-validate" aria-label="Permalink to &quot;12 · Validate&quot;">​</a></h3><p><code>npm run validate-data</code> is the done-signal. Green except for the known English-first locale gaps = ready.</p><hr><h2 id="validation-the-done-signal" tabindex="-1">Validation = the done-signal <a class="header-anchor" href="#validation-the-done-signal" aria-label="Permalink to &quot;Validation = the done-signal&quot;">​</a></h2><p>Author → <code>npm run validate-data</code> → fix what it names → repeat. A program is done when: base + overlay validate, every linked roster entry resolves, images have provenance, the badge (if any) is PD/CC, <strong>every linked mission carries its dispatch</strong>, the prerender entry + index entry exist, and the only remaining reds are the expected non-en-US locale gaps.</p><h2 id="gotchas-learned-in-the-apollo-dogfood" tabindex="-1">Gotchas (learned in the Apollo dogfood) <a class="header-anchor" href="#gotchas-learned-in-the-apollo-dogfood" aria-label="Permalink to &quot;Gotchas (learned in the Apollo dogfood)&quot;">​</a></h2><ul><li><strong>Bundle key carries <code>.json</code>.</strong> The overlay is keyed <code>programs/apollo.json</code> in the bundle; <code>getProgram</code> must request it with the extension. A key without <code>.json</code> silently misses.</li><li><strong>Universal <code>load</code> needs <code>event.fetch</code>.</strong> Relative data URLs (<code>/data/...</code>) throw under global <code>fetch</code> at prerender — thread the page&#39;s <code>fetch</code> through every <code>get*</code> call.</li><li><strong><code>entries()</code> is not automatic.</strong> Every program <code>id</code> must be listed or its page is missing from the build.</li><li><strong>Roster ≠ new content.</strong> Naming a mission in the roster does not model it. Resist the pull to add missions &quot;so the roster links resolve&quot; — name them as context instead. The reverse also binds: a mission or craft that already exists is linked, never left as a context name.</li><li><strong>Badges are PD/CC or nothing.</strong> Don&#39;t reach for a trademarked contractor logo to fill a vehicle&#39;s badge slot; leave it empty (the UI hides it). Confirm the license on the Commons file page, not by eye.</li><li><strong>Dispatches are part of the program, not a follow-up PR.</strong> They ship with the program that motivated them — step 6, every time.</li></ul><hr><p><em>Orrery · program-addition runbook · July 2026 — companion to PRD-029 + programs-editorial-voice.md. Apollo is the reference implementation.</em></p>',48)])])}const m=o(s,[["render",n]]);export{p as __pageData,m as default};
